DROP TABLE IF EXISTS `discrepancies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `discrepancies` (
  `disc_id` int NOT NULL AUTO_INCREMENT,
  `system_id` int NOT NULL,
  `sub_comp_id` int NOT NULL,
  `assigned_to` int NOT NULL,
  `created_user` int NOT NULL,
  `closed_by` int NOT NULL,
  `created_company` int NOT NULL,
  `raised_by` int NOT NULL,
  `is_engineering` int NOT NULL,
  `customer_location` int NOT NULL,
  `title` varchar(100) NOT NULL,
  `description` varchar(4000) NOT NULL,
  `problem_area` int NOT NULL,
  `extent_effect` int NOT NULL,
  `status` int NOT NULL,
  `created_on` int NOT NULL,
  `closed_on` int NOT NULL,
  PRIMARY KEY (`disc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=535 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

