INSERT INTO `usermanuals` VALUES (3,'OilCop PSM Wire Seal Instruction','assets/files/manuals/Oil_Cop_PSM_Wire_Seal_Instruction_Sheet__-20151201221435.pdf','The following document includes instructions on how to install the PSM wire seal. This seal will prevent tampering with the PSM.','1448988275'),(4,'OilCop PSM Owners Manual','assets/files/manuals/Oil_Cop_PSM_Owners_Manual__-20151201221625.pdf','The following document is an owners manual for the PSMs provided by LiquiDynamics.','1448988385'),(11,'Oil Cop Users Manual','assets/files/manuals/Oil_Cop_Users_Manual__-20160204000215.pdf','Operation instructions for system Administrator, Manager and Technician','1454524335'),(13,'Oil Cop Software update','assets/files/manuals/oilcop-update-LQD_R_2_17-32916__-20160329232250.pdf','Ver. LQD_R_2_17 ','1459273970'),(16,'OilCop LQD_T_2_23 Release Notes','assets/files/manuals/oilcop_updates_august_2_2016__-20160912143325.pdf','OilCop LQD_T_2_23 Release Notes','1473690805'),(17,'Typical OilCop Network Intergration','assets/files/manuals/Typical_OilCop_Network_Intergration__-20170206152823.pdf','Typical OilCop Network Intergration','1486394903'),(20,'Open Ports Required to Access OilCop Support ','assets/files/manuals/Ports_to_access_OilCop_Support__-20180216182729.pdf','List of network ports OilCop sends system status,  manager reports, notifications and live help desk support.','1518805649'),(21,'Interfacing OilCop Controller with Local Area Network','assets/files/manuals/OilCop_network_set_up__-20180216184739.pdf','How to Interface OilCop Controller with Local Area Network','1518806859'),(22,'OilCop Installation Guide','assets/files/manuals/OilCop_Installation_Manual__-20180404201056.pdf','Installation Guide','1522872656'),(24,'OilCop tank monitor installation guide','assets/files/manuals/OilCop_Tank_Monitor_Installation_Guide__-20181016131625.pdf','Tank Monitor installation','1539695785'),(25,'OilCop Meter/Pulser Calibration Procedure','assets/files/manuals/OilCop_Calibration_Procedure__-20181130202919.pdf','Meter/Pulser Calibration Procedure','1543609759'),(26,'Meter Calibration Overview','assets/files/manuals/Meter_Calibration_Overview__-20181130203059.pdf','Meter Calibration Overview','1543609859'),(27,'How to setup HTTPS for the OilCop contoller.','assets/files/manuals/Oilcop_HTTPS_Configuration__-20190103191037.pdf','How to setup HTTPS for the OilCop controller.','1546542637'),(31,'OilCop Auto Export Setup Instructions','assets/files/manuals/OilCop_Auto_File_Export_Set_up_Instructions__-20190517144327.pdf','Instructions how to install FTP server on customer computer to receive exported files from OilCop.','1558104207'),(32,'Tank Monitor Wired To Range Extender','assets/files/manuals/Tank-Monitor-Wired-To-Range-Extender__-20210630151859.pdf','These are the instructions for how to wire a TMM to a RAN and setting the address for both','1625066339');
